        <group ref={o2aA}>
          <SciProAtom symbol="O" color={SCI_CPK.O} radius={0.24} quality={quality} />
        </group>
        <group ref={o2aB}>
          <SciProAtom symbol="O" color={SCI_CPK.O} radius={0.24} quality={quality} />
